UPDATE TB_OREM001
SET CO_ID = #{employee.companyId}
,MN_ROLE_TP = #{employee.roleType, typeHandler=UserRoleTypeHandler}
,EMP_NM = #{employee.emplName}
,EMP_STATUS = #{employee.emplStatus}
,DEPT_NM = #{employee.deptName}
,MBL_PHN_NO = #{employee.mblPhoneNo}
,EMAIL = #{employee.email}
,SMS_RCT_YN = #{employee.smsRctYn}
,EMAIL_RCT_YN = #{employee.emailRctYn}
,OFC_PHN_NO = #{employee.ofcPhoneNo}
,REG_ID = #{employee.writer.regUserId}
,REG_DT = #{employee.writer.registrationDate}
,UPD_ID = #{employee.writer.updUserId}
,UPD_DT = #{employee.writer.updateDate}
WHERE EMP_ID = #{employee.employeeId}
